		t.Fatalf("alice reading her own note: got %d, want 200", rec.Code)
	}
	if rec := doReq(h, "GET", "/notes/1", "tok-carol", ""); rec.Code != http.StatusOK {
		t.Fatalf("admin reading alice's note: got %d, want 200", rec.Code)
	}
